package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.widget.TextView;
import androidx.media3.common.*;import androidx.media3.common.audio.AudioProcessor;import androidx.media3.session.*;
import com.google.common.util.concurrent.ListenableFuture;
import java.io.*;import java.nio.*;import java.util.*;import java.util.concurrent.*;
import org.json.JSONObject;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class LiveTranslationTest {
 private final Instrumentation ins=getInstrumentation();
 private Object field(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private String text(Activity a,String name)throws Exception{return ((TextView)field(a,name)).getText().toString();}
 private void proof(String name,JSONObject value)throws Exception{try(OutputStream out=new FileOutputStream(new File(ins.getTargetContext().getFilesDir(),name))){out.write(value.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 private byte[] pcm(String asset)throws Exception{try(InputStream in=ins.getContext().getAssets().open(asset);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1)out.write(block,0,n);byte[] wav=out.toByteArray();ByteBuffer b=ByteBuffer.wrap(wav).order(ByteOrder.LITTLE_ENDIAN);assertEquals(0x46464952,b.getInt());assertEquals(0x45564157,b.getInt(8));int at=12;while(at+8<=wav.length){int tag=b.getInt(at),size=b.getInt(at+4);if(tag==0x61746164)return Arrays.copyOfRange(wav,at+8,at+8+size);at+=8+size+(size&1);}throw new IOException("Missing WAV data");}}
 private File song()throws Exception{byte[] pcm=pcm("singing-twinkle-8s.wav");File f=File.createTempFile("live-sung-",".wav",ins.getTargetContext().getCacheDir());try(OutputStream out=new FileOutputStream(f)){ByteBuffer head=ByteBuffer.allocate(44).order(ByteOrder.LITTLE_ENDIAN);int bytes=pcm.length*8;head.putInt(0x46464952).putInt(36+bytes).putInt(0x45564157).putInt(0x20746d66).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).putInt(0x61746164).putInt(bytes);out.write(head.array());for(int i=0;i<8;i++)out.write(pcm);}return f;}
 @Test public void tapIsBitExactAndReceiverFailureCannotBreakMusic()throws Exception{
  SpeechProcessor p=new SpeechProcessor();p.configure(new AudioProcessor.AudioFormat(48000,2,C.ENCODING_PCM_16BIT));p.flush();byte[] input=new byte[4096];new Random(7).nextBytes(input);ByteArrayOutputStream captured=new ByteArrayOutputStream();
  try{LiveAudioTap.receiver=new LiveAudioTap.Receiver(){public void pcm(ByteBuffer b,int rate,int channels){assertTrue(b.isReadOnly());assertEquals(48000,rate);assertEquals(2,channels);while(b.hasRemaining())captured.write(b.get());}public void reset(){}};ByteBuffer b=ByteBuffer.allocateDirect(input.length);b.put(input).flip();p.queueInput(b);byte[] actual=new byte[input.length];p.getOutput().get(actual);assertArrayEquals(input,actual);assertArrayEquals(input,captured.toByteArray());LiveAudioTap.receiver=new LiveAudioTap.Receiver(){public void pcm(ByteBuffer value,int rate,int channels){throw new IllegalStateException("Injected receiver failure");}public void reset(){}};b.clear();b.put(input).flip();p.queueInput(b);p.getOutput().get(actual);assertArrayEquals(input,actual);assertNull(LiveAudioTap.receiver);}finally{LiveAudioTap.receiver=null;p.reset();}
 }
 @Test public void openingLiveScreenNeverStartsCaptureOrDownloads()throws Exception{
  assertNull(LiveAudioTap.receiver);Context c=ins.getTargetContext();File model=LiveSpeechModels.path(c,LiveSpeechModels.Model.BASE);long before=model.length();LiveLyricsActivity a=(LiveLyricsActivity)ins.startActivitySync(new Intent(c,LiveLyricsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{ins.waitForIdleSync();Thread.sleep(400);ins.runOnMainSync(()->{try{assertNull(field(a,"recognizer"));assertNull(field(a,"translator"));assertNull(LiveAudioTap.receiver);assertEquals(before,model.length());assertTrue(text(a,"status").contains("Iniciar"));}catch(Exception e){throw new RuntimeException(e);}});}finally{ins.runOnMainSync(a::finish);ins.waitForIdleSync();}
 }
 @Test public void actualSungPlaybackIsRecognizedAndTranslatedWithoutLyricsOrMicrophone()throws Exception{
  Context c=ins.getTargetContext();LiveSpeechModels.obtain(c,LiveSpeechModels.Model.BASE,false,()->false,(b,t)->{});File song=song();ListenableFuture<MediaController>[] future=new ListenableFuture[1];ins.runOnMainSync(()->future[0]=new MediaController.Builder(c,new SessionToken(c,new ComponentName(c,PlaybackService.class))).buildAsync());MediaController player=future[0].get(15,TimeUnit.SECONDS);LiveLyricsActivity activity=null;
  try{ins.runOnMainSync(()->{player.pause();player.setRepeatMode(Player.REPEAT_MODE_OFF);player.setShuffleModeEnabled(false);SpeechSettings.save(c,false,false);SpeechSettings.quiet(c,0);player.sendCustomCommand(new SessionCommand(SpeechSettings.COMMAND,Bundle.EMPTY),Bundle.EMPTY);Bundle cancel=new Bundle();cancel.putInt("minutes",0);player.sendCustomCommand(new SessionCommand("sleep",Bundle.EMPTY),cancel);player.setMediaItem(new MediaItem.Builder().setMediaId("actual-singing-no-lyrics").setUri(Uri.fromFile(song)).build());player.prepare();player.play();});
   activity=(LiveLyricsActivity)ins.startActivitySync(new Intent(c,LiveLyricsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final LiveLyricsActivity a=activity;long deadline=SystemClock.elapsedRealtime()+15000;boolean[] ready={false};while(SystemClock.elapsedRealtime()<deadline){ins.runOnMainSync(()->{try{ready[0]=field(a,"player")!=null&&player.isPlaying();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])break;Thread.sleep(100);}assertTrue("Native player not ready",ready[0]);long started=SystemClock.elapsedRealtime(),cpu=android.os.Process.getElapsedCpuTime();ins.runOnMainSync(()->{try{java.lang.reflect.Method method=LiveLyricsActivity.class.getDeclaredMethod("begin",LiveSpeechModels.Model.class,String.class,String.class,boolean.class);method.setAccessible(true);method.invoke(a,LiveSpeechModels.Model.BASE,"en","pt",false);}catch(Exception e){throw new RuntimeException(e);}});
   String[] values={"","",""};boolean[] translated={false};deadline=SystemClock.elapsedRealtime()+180000;while(SystemClock.elapsedRealtime()<deadline){ins.runOnMainSync(()->{try{values[0]=text(a,"original");values[1]=text(a,"translated");values[2]=text(a,"status");String lower=values[1].toLowerCase(Locale.ROOT);translated[0]=(values[0].toLowerCase(Locale.ROOT).contains("star")||values[0].toLowerCase(Locale.ROOT).contains("twinkle"))&&(lower.contains("estrela")||lower.contains("brilh")||lower.contains("cintil"));}catch(Exception e){throw new RuntimeException(e);}});if(translated[0]||values[2].startsWith("Não foi possível"))break;Thread.sleep(200);}
   assertTrue("Actual PCM→recognition→translation failed: "+Arrays.toString(values),translated[0]);long elapsed=SystemClock.elapsedRealtime()-started,cpuMs=android.os.Process.getElapsedCpuTime()-cpu;long[] position={0};ins.runOnMainSync(()->{assertTrue(player.isPlaying());assertEquals("actual-singing-no-lyrics",player.getCurrentMediaItem().mediaId);position[0]=player.getCurrentPosition();});assertTrue(position[0]>5000);proof("live-translation.json",new JSONObject().put("actualOriginal",values[0]).put("actualTranslation",values[1]).put("actualStatus",values[2]).put("firstCaptionMs",elapsed).put("processCpuMs",cpuMs).put("nativeHeapBytes",Debug.getNativeHeapAllocatedSize()).put("fixture","CC0: Dcoetzee, Twinkle Twinkle Little Star, actually sung").put("lyricsCatalogueUsed",false).put("microphoneUsed",false).put("playbackPreserved",true).put("phoneBatteryMeasured",false));android.graphics.Bitmap screenshot=ins.getUiAutomation().takeScreenshot();if(screenshot!=null){try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"live-translation.png"))){screenshot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{screenshot.recycle();}}
   ins.runOnMainSync(a::finish);ins.waitForIdleSync();activity=null;Thread.sleep(400);assertNull("Audio receiver must detach on leaving",LiveAudioTap.receiver);ins.runOnMainSync(()->assertTrue("Leaving live screen must preserve music",player.isPlaying()));
  }finally{if(activity!=null){LiveLyricsActivity a=activity;ins.runOnMainSync(a::finish);ins.waitForIdleSync();}ins.runOnMainSync(()->{player.pause();player.clearMediaItems();MediaController.releaseFuture(future[0]);});song.delete();}
 }
 @Test public void precisionModelRecognizesActualSungWordsAndClosesSafely()throws Exception{
  File model=LiveSpeechModels.obtain(ins.getTargetContext(),LiveSpeechModels.Model.SMALL,false,()->false,(b,t)->{});byte[] data=pcm("singing-mary-8s.wav");float[] samples=new float[data.length/2];ByteBuffer buffer=ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<samples.length;i++)samples[i]=buffer.getShort()/32768f;long started=SystemClock.elapsedRealtime();String value;try(WhisperEngine engine=new WhisperEngine(model)){value=engine.recognize(samples,"en",2);}assertTrue("Unexpected actual sung recognition: "+value,value.toLowerCase(Locale.ROOT).contains("lamb"));proof("live-precision.json",new JSONObject().put("actualOriginal",value).put("processingMs",SystemClock.elapsedRealtime()-started).put("fixture","Public domain: Celestianpower, Mary Had a Little Lamb, actually sung").put("model",model.getName()));
 }
}
